#include <atomic>
#include <chrono>
#include <csignal>
#include <format>
#include <iostream>
#include <thread>

using namespace std::chrono_literals;

namespace {
// The one global in the program: a handler gets only the signal number, so it can reach nothing else.
std::atomic_flag stop_requested;  // since C++20, a default-constructed flag starts clear
}  // namespace

// The only thing the handler does is set the flag: anything else is unsafe here.
extern "C" void on_signal(int /*signal*/) { stop_requested.test_and_set(); }

int main() {
  std::signal(SIGINT, on_signal);
  std::signal(SIGTERM, on_signal);
  int ticks = 0;
  while (!stop_requested.test()) {
    ++ticks;
    std::cout << std::format("tick {}\n", ticks);
    std::this_thread::sleep_for(100ms);
    if (ticks == 3) std::raise(SIGINT);  // stands in for Ctrl+C so the example stops on its own
  }
  std::cout << std::format("stopping after {} ticks\n", ticks);
  std::cout << "saved\n";  // clean-up happens here, in normal code, not in the handler
}

void on_signal(int) {
  std::printf("stopping\n");  // not async-signal-safe: can deadlock inside printf
  save_everything();          // allocates and locks: the same problem
  std::exit(0);               // runs static destructors from inside the handler
}
